            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault301. Cross-Site Scripting (XSS).
        given().accept("application/json")
                .cookies(cookies_userB)
                .contentType("application/json")
                .body(" { " + 
                    " \"username\" : \"<img src=x onerror=alert('XSS')>\", " + 
                    " \"password\" : \"<img src=x onerror=alert('XSS')>\" " + 
                    " } ")
                .post("${baseUrlOfSut}/WebGoat/access-control/users-admin-fix")
                .then()
                .statusCode(200)
                .assertThat()
                .contentType("application/json")
                .body("'username'", containsString("<img src=x onerror=alert('XSS')>"))
                .body("'password'", containsString("<img src=x onerror=alert('XSS')>"))
                .body("'admin'", equalTo(false))
    }
    
    
