    /**
    * Calls:
    * 1 - (200) HEAD:/WebGoat/crypto/signing/getprivate
    * 2 - (500) GET:/WebGoat/service/lessonoverview.mvc/{lesson}
    * 3 - (200) POST:/WebGoat/crypto/signing/verify
    * Found 4 potential faults. Type-codes: 100, 200
    */
    @Test @Timeout(60)
    fun test_97_postOnVerifyShowsFaults_100_200()  {
        
        val cookies_userB : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=userbb&password=userBB")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        val cookies_userA : Map<String,String> = given()
            .contentType("application/x-www-form-urlencoded")
            .body("username=useraa&password=userAA")
            .post("${baseUrlOfSut}/WebGoat/login")
            .then().extract().cookies()
            
        
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.body.missing HEAD on path '/crypto/signing/getprivate' defines a response schema but no response body found.
        given().accept("*/*")
                .cookies(cookies_userB)
                .head("${baseUrlOfSut}/WebGoat/crypto/signing/getprivate")
                .then()
                .statusCode(200)
                .assertThat()
                .body(isEmptyOrNullString())
        
        // Fault100. HTTP Status 500.
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 500 not defined for path '/service/lessonoverview.mvc/{lesson}'.
        given().accept("*/*")
                .cookies(cookies_userA)
                .get("${baseUrlOfSut}/WebGoat/service/lessonoverview.mvc/%7B%7D")
                .then()
                .statusCode(500)
                .assertThat()
                .contentType("application/json")
                .body("'status'", numberMatches(500))
                .body("'error'", containsString("Internal Server Error"))
                .body("'trace'", containsString("java.lang.NullPointerException\n"))
                .body("'path'", containsString("/WebGoat/service/lessonoverview.mvc/%7B%7D"))
        
        // Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.body.schema.type [Path '/feedbackArgs'] Instance type (null) does not match any allowed primitive type (allowed: ["array"])
        given().accept("*/*")
                .cookies(cookies_userB)
                .noContentType()
                .post("${baseUrlOfSut}/WebGoat/crypto/signing/verify?" + 
                    "modulus=b0NyJLVfN&" + 
                    "signature=TfRPsqK_UDQgSx")
                .then()
                .statusCode(200)
                .assertThat()
                .contentType("application/json")
                .body("'assignment'", containsString("SigningAssignment"))
                .body("'attemptWasMade'", equalTo(true))
                .body("'feedback'", containsString("The modulus is not correct"))
                .body("'feedbackArgs'", nullValue())
                .body("'lessonCompleted'", equalTo(false))
                .body("'output'", nullValue())
                .body("'outputArgs'", nullValue())
    }
    
    
